/**
 *  The page's three automatic statuses, computed rather than stored so they
 *  are always current: PASS when "the metric satisfies the requirement",
 *  REJECT when "the metric fails the requirement or is not found in the set
 *  of metrics", PENDING when "metrics were not yet built for the combination
 *  of submission, input dataset, and evaluation library"
 *  (manage-models/set-up-checks). Manual checks return APPROVED on an
 *  eligible approval and PENDING otherwise, because the approved condition is
 *  the only one the page defines. NEVER consulted by create_release: "it is
 *  not mandatory for all checks to be approved before creating a release".
 */
export const submissionCheckStatus = { apiName: 'submission_check_status', kind: 'function' } as FunctionType<
  { p_check: string; p_submission: string },
  string
>

/**
 *  NULL when the action's criteria hold for these parameters; otherwise the
 *  failure message to show. The form can ask before submitting;
 *  apply_action() asks regardless.
 */
export const submissionCriteriaVerdict = { apiName: 'submission_criteria_verdict', kind: 'function' } as FunctionType<
  { p_action_type: string; p_parameters?: Json },
  string
>

/**
 *  The ten operators submission-criteria names, with the descriptions the
 *  page gives. `arity` is what "operators are pre-filtered to only show a
 *  selection valid for the parameter" means.
 */
export const submissionOperators = { apiName: 'submission_operators', kind: 'function' } as FunctionType<
  Record<string, never>,
  { operator: string; arity: string; note: string }[]
>

/**
 *  Derived, never stored — which is also why "proposals linked to that policy
 *  will be refreshed and have their status reevaluated" costs nothing: the
 *  policy is read at ask time. Rejection dominates. Custom policy on a
 *  protected resource counts eligible non-contributor approvals; the default
 *  policy takes one user with edit permissions; unprotected auto-approves
 *  when the contributor's own permissions covered it.
 */
export const taskApprovalStatus = { apiName: 'task_approval_status', kind: 'function' } as FunctionType<
  { p_task: string },
  string
>

/**
 *  The Test rules panel's contract
 *  (authentication/images/rule-based-group-testing.png): simulate a user
 *  against the configured rules and answer with matches, writing nothing.
 */
export const testGroupAssignment = { apiName: 'test_group_assignment', kind: 'function' } as FunctionType<
  { p_user: string },
  Json
>

/**
 *  Test policy, as a named user: total rows in the input's current view
 *  versus rows the policy would show them — evaluated through the same
 *  compiled predicate the readers use.
 */
export const testRestrictedView = { apiName: 'test_restricted_view', kind: 'function' } as FunctionType<
  { p_view: string; p_user: string },
  { visible_rows: number; total_rows: number }[]
>

export const titleKeyEligible = { apiName: 'title_key_eligible', kind: 'function' } as FunctionType<
  { p_base_type: string },
  boolean
>

/**
 *  The datasets a SQL transform names in backticks, resolved within the
 *  repository's project. Foundry's editor rewrites a backtick to a dataset
 *  RID so the code survives a move; ours accepts the RID, the api name, the
 *  name, or a trailing path segment — a recorded simplification of the same
 *  intent (building-pipelines/create-batch-pipeline-cr).
 */
export const transformFileInputs = { apiName: 'transform_file_inputs', kind: 'function' } as FunctionType<
  { p_body: string; p_project: string },
  { dataset_id: string; reference: string }[]
>

/**
 *  The SELECT inside a SQL transform — the body after CREATE TABLE `path` AS,
 *  as the worked example writes it
 *  (building-pipelines/images/finished-code.png). A file with no CREATE TABLE
 *  is taken as the logic itself.
 */
export const transformFileLogic = { apiName: 'transform_file_logic', kind: 'function' } as FunctionType<
  { p_body: string },
  string
>

export const typeWidens = { apiName: 'type_widens', kind: 'function' } as FunctionType<
  { p_from: string; p_to: string },
  boolean
>

/**
 *  The page's definition, not ours: a card is unused only if "It is not
 *  placed on any canvas", "No card on a canvas depends on it" and "It is not
 *  referenced by any dashboard, function, or global settings entity"
 *  (quiver/analysis-canvas). The second is transitive here, since a card
 *  feeding a card that feeds a canvas card is depended on. Quiver functions
 *  and global settings entities are not built, so the third reduces to
 *  dashboards.
 */
export const unusedQuiverCards = { apiName: 'unused_quiver_cards', kind: 'function' } as FunctionType<
  { p_analysis: string },
  { card_id: string; global_id: string; kind: string }[]
>

export const userCanEditResource = { apiName: 'user_can_edit_resource', kind: 'function' } as FunctionType<
  { p_user: string; p_project: string },
  boolean
>

/**
 *  Grammar for user_tools.parameters — every element is {key: lower_snake,
 *  type: text|number|boolean|date, required: bool}.
 */
export const userToolParamsValid = { apiName: 'user_tool_params_valid', kind: 'function' } as FunctionType<
  { p: Json },
  boolean
>

/**
 *  Does a value satisfy the value type's CURRENT constraint — the ontology
 *  never pins a version. NULL conforms (requiredness is the property's
 *  concern). Nested and element recurse through the self-edge, capped at
 *  depth 10 by declared invention.
 */
export const valueConforms = { apiName: 'value_conforms', kind: 'function' } as FunctionType<
  { p_value: Json; p_value_type: string; p_depth?: number },
  boolean
>

/**
 *  One value formatter, typed by the property's base type
 *  (object-link-types/value-formatting): numeric
 *  (currency/unit/percentage/prefix-suffix, notation, digit options and the
 *  capture's negative-to-parenthesis ride free-form keys), datetime (the
 *  published six styles, timezone static or the user's), Multipass username,
 *  resource RID. Artifact GID excluded — no artifacts here.
 */
export const valueFormattingValid = { apiName: 'value_formatting_valid', kind: 'function' } as FunctionType<
  { p_base: string; j: Json },
  boolean
>

/**
 *  Which base types a constraint kind may be applied to, from
 *  value-type-constraints. NULL for an unknown kind. `long` and `byte` are
 *  deliberately absent from enum and range: the page lists neither, and
 *  adding them because they look numeric would be inventing a pairing.
 */
export const valueTypeConstraintBaseTypes = { apiName: 'value_type_constraint_base_types', kind: 'function' } as FunctionType<
  { p_kind: string },
  string[]
>

